CREATE TABLE evaluation_templates(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,origin TEXT NOT NULL,spec_json TEXT NOT NULL,source_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE evaluation_snapshot_origins(snapshot_id TEXT NOT NULL REFERENCES configuration_snapshots(id),profile_id TEXT NOT NULL,origin TEXT NOT NULL,PRIMARY KEY(snapshot_id,profile_id));
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.source.source_snapshot.snapshot_id');
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.model.parameters.snapshot_id');
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.harness.configuration.snapshot_id');
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.execution.environment_snapshot.snapshot_id');
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.execution.sandbox_policy.snapshot_id');
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.execution.sandbox_capabilities.snapshot_id');
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.execution.network_cache_configuration.snapshot_id');
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.grader.configuration.snapshot_id');
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.grader.environment.snapshot_id');
INSERT OR IGNORE INTO evaluation_snapshot_origins SELECT s.id,d.profile_id,'trusted_configuration' FROM runs r JOIN run_details d ON d.run_id=r.id JOIN configuration_snapshots s ON s.id=json_extract(r.spec_json,'$.observability.pricing_snapshot.snapshot_id');
CREATE TRIGGER immutable_evaluation_template BEFORE UPDATE ON evaluation_templates BEGIN SELECT RAISE(ABORT,'evaluation template is immutable'); END;
CREATE TRIGGER immutable_evaluation_snapshot_origin BEFORE UPDATE ON evaluation_snapshot_origins BEGIN SELECT RAISE(ABORT,'configuration origin is immutable'); END;
